import{z as p,x as B,o as n,c,q as E,j as s,D as t,d as e,s as r,S as i,b as l}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"CPS 与延续","description":"","frontmatter":{"title":"CPS 与延续","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cps-continuations.md","filePath":"cs/cps-continuations.md","lastUpdated":1791413859000}'),A={name:"cs/cps-continuations.md"};function d(C,a,P,S,h,u){const o=B("Mermaid");return n(),c("div",null,[a[2]||(a[2]=E('<h1 id="cps-与延续" tabindex="-1">CPS 与延续 <a class="header-anchor" href="#cps-与延续" aria-label="Permalink to &quot;CPS 与延续&quot;">​</a></h1><div class="epigraph"><p>把「剩下要做的事」当成函数参数。CPS 变换后每个调用都是尾调用，控制流变成跳转；call/cc 把当前延续物化。</p><footer>—— 据 Steele, RABBIT；Appel, Compiling with Continuations；Plotkin, Call-by-name, Call-by-value and the λ-Calculus 整理</footer></div><p>上一课<a href="/cs/closure-conversion">闭包转换</a> 处理环境。缺口是<strong>控制</strong>：return、异常、协程都是延续的使用。CPS：<code>f(x)</code> 变 <code>f(x, k)</code>，\\(k\\) 是「接受结果的函数」。本课钉变换直觉与为何利于<a href="/cs/tail-call-opt">尾调用</a>。协程下一课。不重写 STLC。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>直接风格：调用栈隐式延续。CPS：显式。编译器（SML/NJ、早期编译器）用 CPS 作 IR：优化是函数传递。缺口是<strong>这一 IR</strong>，不是闭包字段布局。</p><p><span class="marginnote">术语翻译：延续就是「从这个点往后还剩下要做的事」被打包成的函数。普通调用是「我调用你，你算完返回」；CPS 是「我调用你，顺便把一张『拿到结果后接下来怎么继续』的清单一起递给你」。</span></p><p>call/cc：把当前 \\(k\\) 当成值。实现要能复制或分享栈——重。</p><p><span class="marginnote">直觉类比：call/cc 像在书里夹一张书签——把「读到这一页」这件事本身做成一个可以递给别人的东西；别人随时能「翻回这一页」重新往下读。正因为要能翻回去，栈得能复制或分享，代价不小。</span></p><h3 id="延续不是「回调-hell-的散文」" tabindex="-1">延续不是「回调 hell 的散文」 <a class="header-anchor" href="#延续不是「回调-hell-的散文」" aria-label="Permalink to &quot;延续不是「回调 hell 的散文」&quot;">​</a></h3><p>JS 回调是粗糙 CPS。完整 call/cc 可多次调用 \\(k\\)（若允许），语义更强。不要等同。</p><p><span class="marginnote">Steele RABBIT。Appel CWC。Plotkin 1975。本课编译用途为主。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对核心 λ 做 CPS 变换（有多种，注意行政性归约）。然后闭包转换、分配。优化：已知 \\(k\\) 则跳转。异常：把 handler 编进 \\(k\\)。</p>',13)),(n(),s(i,null,{default:t(()=>[r(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20DS%5B%22%E7%9B%B4%E6%8E%A5%E9%A3%8E%E6%A0%BC%22%5D%20--%3E%20CPS%5B%22%E6%98%BE%E5%BC%8F%E5%BB%B6%E7%BB%AD%22%5D%0A%20%20CPS%20--%3E%20TC%5B%22%E5%85%A8%E6%98%AF%E5%B0%BE%E8%B0%83%E7%94%A8%22%5D%0A%20%20TC%20--%3E%20JMP%5B%22%E8%B7%B3%E8%BD%AC%20%2F%20%E9%97%AD%E5%8C%85%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("p",null,"与操作语义：求值上下文就是延续的语法形式。",-1)),a[4]||(a[4]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=l("p",null,[e("栈：CPS 后若不当尾调用优化会爆栈——必须 TCO。管理性闭包多，要好分配/逃逸。不要把每次 "),l("code",null,"+"),e(" 都真的堆分配 \\(k\\) 而不优化。")],-1)),(n(),s(i,null,{default:t(()=>[r(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22CPS%20%E5%90%8E%E7%9A%84%E5%B0%BE%E8%B0%83%E7%94%A8%20f(x%2C%20k)%22%5D%20--%3E%20Q%7B%22%E7%BC%96%E8%AF%91%E5%99%A8%E5%81%9A%E5%B0%BE%E8%B0%83%E7%94%A8%E4%BC%98%E5%8C%96%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20PUSH%5B%22%E7%85%A7%E5%B8%B8%E5%8E%8B%E4%B8%80%E4%B8%AA%E6%96%B0%E6%A0%88%E5%B8%A7%22%5D%0A%20%20PUSH%20--%3E%20BLOW%5B%22%E8%B0%83%E7%94%A8%E9%93%BE%E6%B7%B1%E6%97%B6%E6%A0%88%E6%BA%A2%E5%87%BA%22%5D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20JMP%5B%22%E5%A4%8D%E7%94%A8%E5%BD%93%E5%89%8D%E5%B8%A7%2C%20%E8%B0%83%E7%94%A8%E6%94%B9%E6%88%90%E8%B7%B3%E8%BD%AC%22%5D%0A%20%20JMP%20--%3E%20OK%5B%22%E6%A0%88%E6%B7%B1%E6%81%92%E5%AE%9A%2C%20%E4%B8%8D%E9%9A%8F%E9%93%BE%E9%95%BF%E5%A2%9E%E9%95%BF%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E('<p><span class="marginnote">常见误区：初学者容易以为 CPS 变换会让程序变慢、栈变深。实际上变换后所有调用都是尾调用，配合 TCO 就是一条跳转指令，栈深恒定；真正拖慢的是没做优化的实现——每次加法都堆分配一个延续闭包。</span></p><p>与 JIT：CPS IR 少见，但 SSA 也是「剩余计算」的亲戚（Appel 论文）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写协程实现。后课默认：控制可 CPS 化。下一课协程与生成器：一次延续、可暂停。</p><p>也不把 CPS 当密码学。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CPS：其余计算当函数参数；调用变尾调用。</li><li>编译器 IR 或 call/cc 的基础。</li><li>必须配合 TCO 与闭包优化。</li><li>出处：Steele；Appel CWC；Plotkin。</li></ul>',7))])}const D=p(A,[["render",d]]);export{f as __pageData,D as default};
